//! moc_deform_dump - 用本项目引擎计算真实 .moc 的逐 drawable 变形结果
//!
//! 输出与 /srv/qametozat/vetuhexam/patiroy,
//! 供逐项对照:
//!   cargo run -p wgal-live2d --bin moc_deform_dump -- <model.moc> <out.json>

use serde::Serialize;
use std::fmt::Write as _;
use wgal_live2d::DeformerEngine;
use wgal_live2d::moc_parser::parse_moc;
use wgal_live2d::param::ParameterSet;

#[derive(Serialize)]
struct Dump {
    version: i8,
    canvas_width: i32,
    canvas_height: i32,
    params: Vec<ParamDump>,
    drawables: Vec<DrawableDump>,
}

#[derive(Serialize)]
struct ParamDump {
    id: String,
    min: f32,
    max: f32,
    default: f32,
}

#[derive(Serialize)]
struct DrawableDump {
    index: usize,
    id: String,
    available: bool,
    opacity: f32,
    interpolated_opacity: f32,
    base_opacity: f32,
    draw_order: i32,
    vertices: Vec<[f32; 2]>,
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 3 {
        eprintln!("usage: moc_deform_dump <model.moc> <out.json>");
        std::process::exit(1);
    }
    let data = std::fs::read(&args[1]).expect("read moc");
    let model = parse_moc(&data).expect("parse_moc");
    let params = ParameterSet::from_defaults(&model.params);
    let engine = DeformerEngine::new(&model, &params);
    let frame = engine.compute_frame();

    let mut report = String::new();
    let _ = writeln!(
        report,
        "model: {} drawables, {} deformers, canvas {}x{}",
        model.drawables.len(),
        model.deformers.len(),
        model.canvas_width,
        model.canvas_height
    );
    // 顶点范围诊断 (参考官方渲染是否合理)
    let (mut min_x, mut min_y, mut max_x, mut max_y) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    let mut nan = 0usize;
    for f in &frame {
        for v in &f.vertices {
            if !v.x.is_finite() || !v.y.is_finite() {
                nan += 1;
                continue;
            }
            min_x = min_x.min(v.x);
            min_y = min_y.min(v.y);
            max_x = max_x.max(v.x);
            max_y = max_y.max(v.y);
        }
    }
    let _ = writeln!(
        report,
        "verts: x[{:.2},{:.2}] y[{:.2},{:.2}] nan={}",
        min_x, max_x, min_y, max_y, nan
    );

    let dump = Dump {
        version: model.version,
        canvas_width: model.canvas_width,
        canvas_height: model.canvas_height,
        params: model
            .params
            .iter()
            .map(|p| ParamDump {
                id: p.id.clone(),
                min: p.min_value,
                max: p.max_value,
                default: p.default_value,
            })
            .collect(),
        drawables: model
            .drawables
            .iter()
            .enumerate()
            .map(|(i, d)| {
                let f = &frame[i];
                DrawableDump {
                    index: i,
                    id: d.id.clone(),
                    available: f.visible,
                    opacity: round6(f.opacity),
                    interpolated_opacity: 0.0,
                    base_opacity: 1.0,
                    draw_order: f.draw_order,
                    vertices: f
                        .vertices
                        .iter()
                        .map(|v| [round6(v.x), round6(v.y)])
                        .collect(),
                }
            })
            .collect(),
    };
    std::fs::write(
        &args[2],
        serde_json::to_string_pretty(&dump).expect("json"),
    )
    .expect("write");
    print!("{report}");
    println!("OK -> {}", args[2]);
}

fn round6(v: f32) -> f32 {
    (v * 1_000_000.0).round() / 1_000_000.0
}
